"""Input subsystem handler — emits the SDL2 event pump and input state."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from src.core.engine_profile import EngineProfile

INPUT_HEADER = """\
#pragma once
// {name} — input subsystem. Generated by sdl2-game-engine-starter.
#include <SDL.h>
#include <array>
#include <cstdint>

namespace {ns}::input {{

enum class Key : std::uint8_t {{ W, A, S, D, Space, Escape, Count }};

class InputState {{
public:
    void pump() noexcept;
    [[nodiscard]] bool held(Key k) const noexcept;
    [[nodiscard]] bool quit_requested() const noexcept {{ return quit_; }}

private:
    std::array<bool, static_cast<std::size_t>(Key::Count)> held_{{}};
    bool quit_ = false;
}};

}}  // namespace {ns}::input
"""

INPUT_SOURCE = """\
// {name} — input subsystem implementation.
#include "input/input_state.h"

namespace {ns}::input {{

static bool key_from_scancode(SDL_Scancode sc, Key& out) noexcept {{
    switch (sc) {{
        case SDL_SCANCODE_W:      out = Key::W;      return true;
        case SDL_SCANCODE_A:      out = Key::A;      return true;
        case SDL_SCANCODE_S:      out = Key::S;      return true;
        case SDL_SCANCODE_D:      out = Key::D;      return true;
        case SDL_SCANCODE_SPACE:  out = Key::Space;  return true;
        case SDL_SCANCODE_ESCAPE: out = Key::Escape; return true;
        default: return false;
    }}
}}

void InputState::pump() noexcept {{
    SDL_Event ev;
    while (SDL_PollEvent(&ev)) {{
        if (ev.type == SDL_QUIT) {{ quit_ = true; continue; }}
        if (ev.type != SDL_KEYDOWN && ev.type != SDL_KEYUP) continue;
        Key k;
        if (!key_from_scancode(ev.key.keysym.scancode, k)) continue;
        held_[static_cast<std::size_t>(k)] = (ev.type == SDL_KEYDOWN);
    }}
}}

bool InputState::held(Key k) const noexcept {{
    return held_[static_cast<std::size_t>(k)];
}}

}}  // namespace {ns}::input
"""


@dataclass(slots=True)
class InputHandler:
    profile: EngineProfile

    @property
    def namespace(self) -> str:
        return self.profile.name.replace("-", "_").lower()

    def emit(self, project_root: Path) -> list[Path]:
        out_dir = project_root / "src" / "engine_cpp" / "input"
        out_dir.mkdir(parents=True, exist_ok=True)
        ns = self.profile.name.replace("-", "_").lower()
        header = out_dir / "input_state.h"
        source = out_dir / "input_state.cpp"
        header.write_text(INPUT_HEADER.format(name=self.profile.name, ns=ns), encoding="utf-8")
        source.write_text(INPUT_SOURCE.format(name=self.profile.name, ns=ns), encoding="utf-8")
        return [header, source]